runs.command_script:
$ErrorActionPreference='Stop'
. ./tests/TestSupport.ps1
Import-Module "$env:TEMP/wvc-m0-02-dev-modules/PSScriptAnalyzer/1.24.0/PSScriptAnalyzer.psd1"
$cases=@()
foreach ($file in @('tests/integration/New-CancelManualFixture.ps1','tests/integration/Test-CancelManualResult.ps1')) {
    $tokens=$null; $errors=$null
    [void][Management.Automation.Language.Parser]::ParseFile((Join-Path $PWD $file),[ref]$tokens,[ref]$errors)
    $cases+=New-WvcTestCase ($file+'/parse') $(if ($errors.Count) {'Failed'} else {'Passed'})
    $diagnostics=@(Invoke-ScriptAnalyzer -Path $file -Settings ./PSScriptAnalyzerSettings.psd1)
    $cases+=New-WvcTestCase ($file+'/analyzer') $(if ($diagnostics.Count) {'Failed'} else {'Passed'})
    $bytes=[IO.File]::ReadAllBytes((Join-Path $PWD $file))
    $cases+=New-WvcTestCase ($file+'/ASCII') $(if (@($bytes | Where-Object {$_ -gt 127}).Count) {'Failed'} else {'Passed'})
}
$summary=Get-WvcTierSummary Quick $cases
$report=[pscustomobject]@{SchemaVersion=1;SourceCommit=(& git rev-parse HEAD | Out-String).Trim();
    Dirty=[bool]@(& git status --porcelain=v1 --untracked-files=all).Count;
    PowerShell=$PSVersionTable.PSVersion.ToString();Status=$summary.Status;ExitCode=$summary.ExitCode;
    Counts=$summary.Counts;Cases=$cases;ApplicationSHA256=(Get-FileHash -LiteralPath ./WinVidCompress.ps1).Hash}
Write-WvcTestJson .test-results/m306/helper-static.json $report
exit $summary.ExitCode
